import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        小筐 左筐 = new 小筐();
        小筐 右筐 = new 小筐();
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            if (x % 2 == 0) {
                左筐.收一件();
            } else {
                右筐.收一件();
            }
        }
        System.out.println("左筐 " + 左筐.报件数() + " 件");
        System.out.println("右筐 " + 右筐.报件数() + " 件");
    }
}

class 小筐 {
    int 件数 = 0;

    void 收一件() {
        件数 = 件数 + 1;
    }

    int 报件数() {
        return 件数;
    }
}
